mapper.select:
SELECT os.id, os.case_id, os.name, ac.name AS case_name, CASE COALESCE(os.protocol_type, ac.protocol_type) WHEN 1 THEN 'HTTP' WHEN 2 THEN 'DUBBO' ELSE 'UNKNOWN' END AS protocol_type, COALESCE(os.protocol_type, ac.protocol_type) AS protocol_type_num, COALESCE(os.request_type, CASE ac.request_type WHEN 0 THEN 'GET' WHEN 1 THEN 'POST' WHEN 2 THEN 'PUT' WHEN 3 THEN 'DELETE' WHEN 4 THEN 'PATCH' ELSE NULL END ) AS request_type, COALESCE(os.address, ac.address) AS address, os.request_headers, os.request_body, os.is_available, os.input_params, os.output_params, os.assertions, os.service_type, os.application_id, app.name AS application_name, dept.name AS department_name, os.creator_id, os.owner_id, os.updater_id, os.created_at, os.updated_at FROM original_service os LEFT JOIN api_case ac ON os.case_id = ac.id AND ac.deleted = 0 LEFT JOIN application app ON os.application_id = app.id AND app.deleted = 0 LEFT JOIN department dept ON app.department_id = dept.id AND dept.deleted = 0 WHERE os.deleted = 0
AND os.name LIKE CONCAT('%', #{keyword}, '%')
AND os.application_id = #{applicationId}
AND os.is_available = #{isAvailable}
ORDER BY os.updated_at DESC

SELECT ac.id, ac.name, ac.address, CASE ac.protocol_type WHEN 1 THEN 'HTTP' WHEN 2 THEN 'DUBBO' ELSE 'UNKNOWN' END AS protocol_type, CASE ac.request_type WHEN 0 THEN 'GET' WHEN 1 THEN 'POST' WHEN 2 THEN 'PUT' WHEN 3 THEN 'DELETE' WHEN 4 THEN 'PATCH' ELSE 'UNKNOWN' END AS request_type, app.name AS application_name, ac.application_id FROM api_case ac LEFT JOIN application app ON ac.application_id = app.id AND app.deleted = 0 WHERE ac.deleted = 0
AND ac.id NOT IN
#{caseId}
AND ac.name LIKE CONCAT('%', #{keyword}, '%')
AND ac.application_id = #{applicationId}
AND ac.protocol_type = #{protocolType}
ORDER BY ac.updated_at DESC
